    suggestedStructure: "序論で人口変動と経済成長の関係を人口ボーナス・オーナスの概念で定義し問いを立て、本論で先進国（例：日本・ドイツ）の人口オーナスと途上国（例：サブサハラアフリカ）の人口ボーナスを対比しながら政策的含意を論じ、結論で両者の課題を国際的な相互補完の観点からまとめて自分の主張を提示する。",
