      "経済産業省の資料では、日本のデジタル関連投資はGDP比でアメリカや欧州主要国と比べて低水準であり、DX（デジタルトランスフォーメーション）の遅れが製造業・サービス業双方の生産性改善を妨げているという指摘がある",
      "少子高齢化により生産年齢人口（15〜64歳）が減少し続けており、労働力不足を補うために一人当たり生産性の向上が国家的課題となっている",
