      "製造業からサービス業・知識集約型産業への転換は都市部への経済集中をもたらしやすく、地方経済の疲弊や地域間格差拡大という社会的影響を切り口にすることができる",
      "労働生産性の向上を追求することで長時間労働の是正や働き方改革につながるという肯定的側面と、効率化優先が労働者の人間的尊厳や雇用の安定を損ねるという否定的側面を対比させる論じ方がある",
      "グリーン産業・再生可能エネルギー分野への産業転換は生産性向上と環境負荷低減を両立し得るが、既存産業（化石燃料関連など）からの移行コストや雇用喪失をどう社会が吸収するかという移行期の公正性（ジャスト・トランジション）の問題として論点化できる",
