    suggestedStructure: "序論でデータを用いて日本の労働生産性の国際的位置づけと産業構造のサービス化という現状を端的に示し、本論では産業構造変化がもたらす雇用・所得分配・地域格差への具体的影響を複数の視点から分析したうえで、結論では課題解決に向けた方向性（DX推進・教育投資・社会保障との連携など）を自分の意見として提示するという流れが効果的である。",
