      "人道的介入とR2Pをめぐる緊張：人権・民間人保護という普遍的価値のために主権を制限できるかという論点。シリア内戦やウクライナ事例を参照しつつ、介入の正当性基準が恣意的に運用されるリスクも検討できる。",
      "経済的グローバル化が主権に与える圧力：WTOやIMFなど経済的国際機関が国内政策に課す制約を通じて、「経済主権」が実質的に侵食されているという視点。自由化圧力と国内産業保護政策の対立を具体的に扱える。",
      "国際法の「ソフトロー化」とその評価：条約のような硬い法的拘束より、指針・宣言・任意基準といったソフトローが拡大する傾向について、主権尊重と実効性のバランスという観点から賛否を論じる視点。",
      "国際法の普遍性と文化的・地政学的多様性の摩擦：西洋主導で形成されてきた国際法秩序に対し、グローバルサウスや権威主義国家が異議を唱える動きを踏まえ、国際法の正統性そのものを問い直す視点。",
