    suggestedStructure: "序論でグローバル化による国際法と国家主権の緊張関係を問題提起し、本論前半でICCやR2Pなど具体的事例を挙げて主権制約の現実と限界を多角的に分析し、本論後半で自国の利益追求と国際秩序維持のバランスという観点から自分の立場を論じ、結論で主権と国際法が補完的に機能するための条件や今後の展望を簡潔にまとめる。",
