      "家庭裁判所に送致された少年のうち大多数は保護観察や少年院送致といった保護処分が適用されており、再犯率の抑制に一定の効果があるとされている",
      "成年年齢引き下げにより18・19歳は選挙権行使・契約締結など法的に自己決定を求められる一方、刑事責任の扱いをどう整合させるかという制度的矛盾が指摘されている",
      "脳科学・発達心理学の知見では前頭前野の発達は20代前半まで続くとされており、衝動制御や判断能力の未熟さを根拠に若年者への特別扱いを支持する議論がある",
