    suggestedStructure: "序論で少年法の理念と近年の法改正の経緯を整理しつつ自分の立場を明示し、本論では更生の観点（可塑性・保護処分の効果）と処罰の観点（法的整合性・被害者保護・抑止力）を具体的根拠とともに比較検討し、結論で両観点を踏まえた上で年齢引き下げの是非について自分の主張を「特定少年制度の評価」を軸に論理的に締めくくる。",
