      "FAO食料価格指数は2022年に史上最高値を更新し、エネルギー・肥料コスト上昇との複合効果で農業生産コストが世界的に増大した",
      "気候変動による異常気象（干ばつ・洪水・熱波）は農業生産の不安定要因となっており、IPCCは温暖化が進むほど主要穀物の収量低下リスクが高まると指摘している",
      "食料ロス・廃棄は世界全体の生産量の約3分の1に相当するとFAOは推計しており、供給側の非効率が潜在的な食料不足を拡大させる構造的要因として注目されている",
