      "経済的不平等と食料アクセスの視点。食料の絶対的生産量は足りていても所得格差・インフラ不足・債務問題により途上国が食料を購入・輸送できない「分配の失敗」として問題を捉える角度",
      "エネルギー・肥料コストとの連鎖的因果関係の視点。化石燃料価格の上昇が化学肥料コストを押し上げ、農業生産コストを増大させ、食料価格に転嫁されるという連鎖を経済学的に説明できる",
      "短期的ショック要因と長期的構造要因を区別する視点。戦争・異常気象などの短期的トリガーと、人口増加・気候変動・農地劣化という長期的構造要因の両面から因果関係を整理することで、論述に深みをもたせられる",
