      "数値化がもたらす社会的影響という視点。数値化することで愛情が比較・競争の対象になりうるという弊害と、数値化によって自分や相手の感情を客観視し関係改善に役立てられるという利益のバランスをどう考えるか",
      "文化・哲学的視点として、西洋の分析的・科学主義的アプローチと、愛情を言語化・数値化すること自体をタブー視したり神聖視する文化的・宗教的立場との対比",
