      "自文化中心主義（エスノセントリズム）の克服という観点で、異文化を理解するには自文化を相対化して見る内省的姿勢が不可欠であるという論点を立てられる",
      "表面的な文化交流と深層的な価値観理解の違いという軸で、料理や音楽などの文化消費にとどまる浅い理解と、歴史的背景や社会構造への理解を伴う深い相互理解の差異を問える",
