      "2022年の安倍元首相銃撃事件を契機に旧統一教会と政治の関係が社会問題化し、宗教法人法の見直しや献金規制を盛り込んだ被害者救済法が同年12月に成立した",
      "NHKや内閣府の調査では若年層を中心に特定の宗教を信じないと答える割合が増加傾向にあるものの、スピリチュアリティや非制度的宗教への関心は根強く残っている",
      "世界的にはイスラーム人口が増加傾向にあり、ピュー・リサーチセンターの予測では2050年頃にキリスト教人口と並ぶ規模に達するとされ、多宗教共存の問題が国際社会の重要課題となっている",
      "東日本大震災以降、宗教者による傾聴ボランティアや臨床宗教師の養成が広がり、宗教の社会的・ケア的機能が再評価される動きが日本国内で続いている",
