      "中小企業庁の資料によれば、地方の中小企業の多くは研究開発投資の余力が乏しく、大学の知見や人材を活用したいと考える企業は多いが、連携の入口となる情報やコーディネート機能が不足していると指摘されている",
      "広島県は自動車・造船などものづくり産業を基盤とするが、デジタルトランスフォーメーションや脱炭素化への対応が急務とされており、大学との連携による技術転換支援が政策課題となっている",
