      "大学が知識・人材の供給者にとどまるモデルから、大学自体が地域のプラットフォームとなるモデルへの転換の必要性という視点",
      "産学連携の成果が大都市圏の大企業に吸収されてしまい地域に還元されないという「知的資源の流出」リスクをいかに防ぐかという視点",
      "地域の中小企業が産学連携に参画するための障壁（コスト・情報・信頼関係）を誰がどのように取り除くべきかという制度設計の視点",
      "人口減少下において産学連携が地元就職率の向上や若者の定着にどの程度寄与できるか、経済活性化の手段としての実効性を問う視点",
