    suggestedStructure: "序論では与えられた工学的テーマや課題の核心を明確に定義し、自分がどの立場・視点から論じるかを提示する。本論では問題の背景・原因分析を行ったうえで工学的手法や論理的根拠に基づく解決策・考察を展開し、想定される反論や限界にも言及することで思考の深さを示す。結論では本論の論点を簡潔に統合し、工学的観点からの今後の展望や自らの学びへの意欲を添えて締めくくる。",
