      "高校数学で培われる演算スキルと、大学数学で必要とされる抽象的論証能力の間のギャップをこの入試形式がどのように橋渡ししているかを分析する視点",
      "理学部数学科という基礎科学の場において、応用可能性や社会貢献よりも純粋な論理的思考力を選抜基準の中心に置くことの意義と課題を問う視点",
