    suggestedStructure: "序論では数学論述試験が単なる計算能力テストと異なる理由を問いとして提示し、本論では自身が取り組んだ問題に対して複数のアプローチを比較しながら思考過程を段階的に記述し、結論では選択した解法の論理的妥当性と限界を自己評価する形で締めくくることで、思考の透明性と数学的誠実さを示す構成が有効である。",
