      "農業や地域行事と結びついた季節の節目（春分・秋分・勤労感謝など）は、地方経済や伝統文化の継承と関連しており、日付変更には社会的コストが伴う",
      "GDPに占める個人消費の割合が約5割を超える日本において、休暇配置による消費喚起は内需拡大策の一つとして経済学的に注目されてきた",
