      "法の支配・適正手続の観点から、監視技術の利用には明確な法的根拠・令状主義・比例原則・司法審査が不可欠であり、行政裁量への委任が広すぎることの危険性を指摘する視点",
      "監視社会化が「萎縮効果」をもたらし、市民が監視を意識するだけで表現・集会・思想の自由を自己抑制するという、プライバシー侵害の間接的・構造的害悪に着目する視点",
      "国際比較（GDPR型の権利保護重視モデルと米国型の利活用重視モデルの差異など）を踏まえ、日本がどの方向性で立法・解釈論を構築すべきかという政策的・比較法的視点",
