      "世界銀行の推計によると、新型コロナウイルス感染症の影響などにより、2022年時点でも世界人口の約8.4パーセント（約6億9500万人）が1日1.9ドル未満で生活する極度の貧困状態に置かれている。",
      "日本政府は2023年に改正入管法を成立させ、外国人の在留管理や難民認定制度の見直しを行ったが、人権保護の観点から国際社会や国内NGOから批判を受けており、国内外の制度的課題を象徴する出来事となっている。",
