    suggestedStructure: "序論でグローバル化と文化的多様性の保護が矛盾する構造を簡潔に示し問いを立て、本論では均質化のリスクと混交・共存の可能性という二つの側面を具体的事例と政策論を交えて分析したうえで、結論では国家・国際機関・市民社会それぞれが果たすべき役割を提示しながら両立のための条件を自分の言葉で主張する。",
