      "児童虐待防止法（2000年制定、その後複数回改正）や配偶者暴力防止法（DV 防止法、2001年制定）は、従来は私的領域とされた家庭内行為に国家が介入する法的枠組みを明示した代表例である",
      "欧州人権裁判所の判例等では、家庭生活の尊重権（欧州人権条約8条）と国家の積極的義務の衝突が繰り返し争われており、介入の比例原則が重要な判断基準とされている",
      "少子化・家族形態の多様化を背景に、同性カップルや事実婚家庭に対する法的保護の在り方をめぐり、国家が「家族」を定義・規律することの正当性が議論されている",
