      "国家が「正常な家族像」を法制度を通じて定義することで、多様な家族形態を排除・周縁化するリスクという文化的・倫理的論点",
      "積極的国家観（社会権・福祉国家）の立場から介入を正当化する論理と、消極的国家観（自由権・夜警国家）の立場から介入を抑制する論理という国家観の根本的差異",
