    suggestedStructure: "序論では立憲主義の定義と家庭の自律性保護という原則を提示し、介入の是非という問いを明確化する。本論では介入を肯定する根拠（弱者保護・憲法24条の積極的義務）と否定する根拠（プライバシー権・権力制限原理）を対比したうえで比例原則を判断基準として示し、結論では一律の肯否ではなく権利侵害の明白性と手段の最小限性を条件とした限定的介入容認という立場を自分の言葉で述べる。",
