    suggestedStructure: "序論では自由・民主主義・人権が国際的に普遍的価値とされてきた経緯を概観しつつ、現代においてその普遍性が問われている背景を示す。本論では普遍主義と文化相対主義の対立、および国家主権と人権保護の緊張関係という二つの論点を軸に自分の立場を示し、その根拠を具体的事例や法的枠組みを用いて論証する。結論では国際社会と日本がこれらの価値を守り発展させるために必要な姿勢や制度的取り組みを提言する形でまとめる。",
