      "技術の中立性と権力の非対称性という視点から、脳デバイスや遺伝子操作は技術自体は中立でも、それを管理する国家権力との力関係が問題となることを論じる角度",
      "同意と強制の境界線という視点として、本人の自発的同意に基づく利用と、国家が強制的に施す管理では倫理的評価が大きく異なるという論点を整理する切り口",
      "人間の本質的定義をめぐる哲学的視点として、脳や遺伝子を外部から改変された存在が依然として同一の人格・権利主体といえるのかという問いから、人権の根拠そのものを問い直す角度",
      "法的規制の実効性という現実論として、仮に管理国家を容認する法整備が進んだとしても、その法自体を管理者側が恣意的に運用するリスクをどう防ぐかという制度設計上の問題を論じる視点",
