    suggestedStructure: "序論でディストピア小説が提示する管理国家の問題設定を整理しつつ自分の立場を明示し、本論前半で賛成論（安全保障・犯罪抑止・社会効率）を具体的根拠とともに示し、本論後半で反対論（思想の自由・人格の尊厳・権力濫用リスク・ニューロライツ）を法的観点から展開したうえで、結論で両論を踏まえつつ技術の利用条件として不可欠な本人同意・独立した監視機関・法的歯止めの三点に言及し自分の見解を締めくくる。",
