      "日本の葬儀の約90%が仏式で行われるという調査報告があり、仏教は「葬式仏教」と呼ばれる側面が強い一方、この慣習自体が少子高齢化や家族形態の変化によって変容しつつある",
      "全国の寺院数は約77,000か所とされ、コンビニエンスストアの店舗数（約55,000店）を上回るが、後継者不足や檀家減少により約2万か所が無住寺院と推計されるという指摘もある",
      "東日本大震災（2011年）以降、被災地での「心のケア」として宗教者・僧侶によるグリーフケア活動が注目され、仏教の社会的役割としての臨床宗教師制度が2016年前後から各大学で整備されはじめた",
