      "制度としての仏教と実践としての仏教という視点：檀家制度や葬祭儀礼という慣習的・制度的側面と、瞑想・修行・慈悲の実践という内面的・実践的側面を区別し、現代社会でどちらがより意義を持つかを論じることができる",
      "仏教の社会貢献という視点：臨床宗教師によるグリーフケア、寺院を拠点とした子ども食堂・居場所づくり、高齢者福祉など、仏教が現代的な社会課題に応答する具体的事例を軸に論じることができる",
      "アイデンティティと宗教という視点：若年層の「なんとなく仏教徒」という曖昧な宗教意識が日本社会の文化的基盤に与える影響を問い、仏教的価値観（無常観・縁起・慈悲など）が意識されないまま社会通念に溶け込んでいるという論点を展開できる",
