      "文学の社会的機能：文学を審美的・自律的な芸術として捉える立場と、社会変革や共感形成のための実践的ツールとして捉える立場を対比させる",
      "自国文化とのクロスカルチャー比較：英語圏文化の特徴を日本文化と比較することで相対化し、異文化理解が自己理解にもつながるという視点から論じる",
