    suggestedStructure: "序論で英語圏文化または文学における具体的なテーマや作品を提示し自分の問いを明確にする。本論では一つの論点について賛否・複数の視点を挙げながら根拠を示して論じ、結論で自分の立場を改めて示しつつ英語圏文化を学ぶ意義に言及してまとめる。",
