    suggestedStructure: "序論では古典文学が現代において軽視されがちな現状や問いを提示し、本論では具体的な作品や場面を例に挙げながら現代人の精神・言語・文化アイデンティティへの示唆を複数の角度から論じ、結論では古典との向き合い方についての自分なりの主張と国文学を学ぶ自己の姿勢へと収束させる。",
