  "pq-komazawa-mgmt-n1": {
    backgroundKnowledge: "企業の社会的責任（CSR）とは、企業が利益追求にとどまらず、環境・社会・従業員・地域社会などへの配慮を経営に組み込む考え方であり、1990年代以降に国際的に普及した。ESG経営とはEnvironment（環境）・Social（社会）・Governance（ガバナンス）の三軸で企業を評価・経営する手法で、2006年に国連が提唱したPRI（責任投資原則）を契機に投資家からも注目されるようになった。日本では2015年にGPIF（年金積立金管理運用独立行政法人）がPRIに署名したことで国内企業のESG対応が加速し、東京証券取引所のコーポレートガバナンス・コードでもESG情報開示が求められるようになった。近年は「SDGs」との連携も強調され、CSR・ESGは企業の存続戦略として不可欠な経営課題となっている。",
    keyFacts: [
      "東京証券取引所は2022年のプライム市場再編に伴い、プライム上場企業に対してTCFD（気候関連財務情報開示タスクフォース）提言に基づく情報開示を実質的に求めるようになり、ESG情報開示の制度化が進んでいる。",
      "GPIFは2023年度末時点で約150兆円規模の運用資産を持ち、ESG投資を積極的に推進していることから、機関投資家によるESG評価が日本企業の資金調達コストに直接影響する構造が生まれている。",
      "経済産業省の調査によれば、国内の大企業を中心にサプライチェーン全体での温室効果ガス排出量（スコープ3）の把握・削減要請が取引先中小企業にも波及しており、CSR対応が企業規模を問わず求められる状況になっている。",
      "2023年に改正された「GX推進法（脱炭素社会の実現に向けた電気供給体制の確立を図るための電気事業法等の一部を改正する法律）」など、環境規制の強化が相次いでおり、企業のESG対応は法的コンプライアンスとも密接に結びついている。",
      "ステークホルダー資本主義の観点から、米国のビジネス・ラウンドテーブルは2019年に株主第一主義からの転換を宣言しており、企業の目的を株主利益のみでなく社会全体への貢献と再定義する国際的な潮流が強まっている。",
    ],
    argumentAngles: [
      "CSR・ESGは企業にとってコスト負担なのか、それとも中長期的なリスク管理や競争優位性の源泉となる戦略的投資なのか、という対立軸から経営合理性を問う視点。",
      "株主利益最大化を重視する伝統的な資本主義的経営観と、従業員・顧客・地域社会・環境も含むステークホルダー全体を重視するステークホルダー資本主義との対比。",
      "CSR・ESG活動が企業の自発的・自律的取り組みにとどまるべきか、それとも法規制や情報開示義務によって制度的に強制されるべきかという、自主規制対公的規制の観点。",
      "大企業と中小企業ではESG対応能力に格差があるという現実を踏まえ、経営資源が限られた企業でも実践可能な社会的責任の形はどうあるべきかという現実的実行可能性の視点。",
      "ESGの「見せかけ（グリーンウォッシュ）」問題を取り上げ、実質を伴わないCSR活動が企業の信頼を損なうリスクを指摘しつつ、真の社会的責任経営に必要な要件を考察する視点。",
    ],
    suggestedStructure: "序論でCSRおよびESG経営の定義と現代的意義を簡潔に示し、本論では「企業にとっての戦略的意義」と「社会・ステークホルダーへの貢献」という二つの側面を具体例や対立意見への反論を交えながら論じ、結論で企業と社会が共存共栄するための経営のあり方について自分の見解を明確に述べる構成が有効である。",
  },
