      "製造・小売・金融など多くの業種で、既存企業がデジタルネイティブ企業やスタートアップによる市場参入（デジタルディスラプション）に直面している",
      "DX推進には経営トップのコミットメントが不可欠とされており、単一部門の取り組みにとどまらず全社的な組織変革が求められるという点が共通認識となっている",
