      "技術導入そのものではなく、組織文化や人材・リーダーシップの変革こそがDX成功の鍵であるという視点と、技術投資が先行すべきという視点の対比",
      "大企業と中小企業でDX推進の環境・課題が大きく異なるという規模の問題を取り上げ、日本経済全体への影響を考察する視点",
