      "ハーバード大学の政治学者サミュエル・ハンチントンが1993年に提唱した「文明の衝突」論は、冷戦後の国際対立が宗教・文化的断層線に沿って生じると主張し、異文化対話の必要性を議論する上で現在も重要な参照点となっている",
