    suggestedStructure: "序論で自身の具体的な経験や社会的事実を挙げて異文化理解の重要性を問題提起し、本論では異文化理解を妨げる要因（先入観・言語障壁・制度的不備など）と促進する方策を複数の視点から掘り下げ、結論でグローバル社会における自己の役割や今後の学びへの意志と結びつけてまとめる。",
