    suggestedStructure: "序論でAI・情報技術が社会変革をもたらしている現状を簡潔に示し問題提起をした後、本論では技術がもたらす恩恵と課題（倫理・格差・雇用など）を具体例を挙げて多角的に論じ、結論では課題解決に向けて人間社会はどうあるべきかという自らの立場を明示して締めくくる構成が有効である。",
