    suggestedStructure: "まず自分が問題意識を持つ具体的な社会課題やマネジメント上の問題を一つ明確に提示し、その背景と現状を簡潔に示す序論から入る。本論では課題の原因を多角的に分析しながら自分なりの解決策をマネジメントの観点から提案し、その実現可能性や想定される課題も率直に論じることで思考の深さを示す。結論では解決策の意義を社会全体や将来世代への影響と結びつけて締めくくり、自分がこの分野でどう貢献したいかという意欲を自然な形で盛り込むと面接との一貫性も生まれる。",
