    suggestedStructure: "序論で自分が問題意識を持つ具体的な社会課題を一つ提示し、なぜそれがビジネスで解決できると考えるかを述べる。本論では課題の背景・現状の限界・自分が考えるビジネスモデルの概要を論じ、利益と社会貢献の両立可能性にも言及する。結論で、起業を通じた社会課題解決の意義と自分がマネジメントを学ぶ動機へとつなげてまとめる。",
