      "日本の2022年度温室効果ガス排出量は約11.3億トンCO2換算（環境省公表）であり、2013年度比で約20%削減されたが、2050年カーボンニュートラル達成には技術的ブレークスルーがなお必要とされている",
      "世界経済フォーラムの2023年版グローバルリスク報告書では、気候変動対策の失敗・自然災害・生物多様性の損失が上位リスクに挙げられており、科学技術による早期対応の重要性が強調されている",
