      "特別支援学校・特別支援学級に在籍する児童生徒数は増加傾向にあり、インクルーシブ教育の理念と分離教育的実態のギャップが課題として指摘されている",
      "合理的配慮の提供には個別の教育支援計画の作成が前提となるが、教員一人当たりの業務負担増大が現場での実施を妨げる要因として報告されている",
      "日本の通常学級における特別支援教育の専門免許保有教員の割合は低く、教員養成段階での特別支援教育に関する必修科目の拡充が近年議論されている",
