      "探究評価型は高校での探究活動の成果をプレゼンテーションと口頭試問で評価する形式であり、高校学習指導要領の「総合的な探究の時間」の導入（2022年度から年次進行で本格実施）と連動している",
      "国際学部のグローバル選抜では筆記審査の過去問が公式サイトで公開されており、透明性の確保と受験生への情報開示が図られている",
