    argumentAngles: [
      "国家主権と国際協調の緊張関係：主権国家システムを尊重しながらいかに実効的な国際ルールを形成・執行するかという対立軸で、一国主義と多国間主義のどちらが課題解決に有効かを論じることができる",
      "経済発展と持続可能性のトレードオフ：途上国が経済成長を追求する権利と、地球環境の限界を守る義務をどう両立させるかという南北問題の視点から論述を組み立てられる",
      "個人の人権と集団・国家の利益の衝突：難民受け入れや少数民族保護をめぐり、普遍的人権規範と各国の社会・文化的文脈の間にある緊張を軸として論じることができる",
      "技術革新による解決可能性の評価：再生可能エネルギーやデジタル技術がグローバル課題を緩和するという楽観論と、技術格差や新たなリスクを生む悲観論を比較する視点",
      "市民社会・NGOと政府・国際機関の役割分担：国連やWTOなど既存の国際制度の限界を踏まえ、非国家主体が果たすべき役割を強調する論点から自分の提言を導くことができる",
    ],
    suggestedStructure: "序論では取り上げる国際課題（例：気候変動と貧困の連鎖など）を具体的に定義し問題の深刻さを示す。本論では原因・現状・対立する解決策を比較検討しながら自分の立場を論拠とともに述べ、結論では国際社会全体と個人・日本がとるべき行動を現実的に提言してまとめる。",
