      "2015年に採択されたパリ協定は国家自主決定貢献（NDC）という自発的枠組みを採用しており、法的拘束力のある排出削減義務がないため達成状況の担保が弱いと指摘されている",
      "ロシアによる2022年のウクライナ侵攻では、安保理でロシアが拒否権を行使したため国連安保理による制裁決議が機能せず、緊急特別総会への場の移行という形で対応せざるを得なかった",
      "国際刑事裁判所（ICC）は2002年設立だが、米国・中国・ロシア・インドなど主要国が未加盟または脱退を表明しており、普遍的な法の支配の実現にはほど遠い状況が続いている",
