      "既存の国際機関の正統性と代表性の問題：安保理の構成やIMF・世界銀行の議決権配分が旧来の権力構造を反映しており、新興国・途上国の声が十分に反映されていないという民主的正統性の問題を取り上げられる",
      "非国家アクターの台頭とガバナンスの多層化：NGO・多国籍企業・市民社会・プラットフォーム企業などが国境を越えた影響力を持つ中で、政府間機関中心の従来モデルが実態に追いついていないという視点を活用できる",
      "機能別アプローチの可能性と限界：気候・保健・貿易など分野ごとに専門機関を設けるセクター別ガバナンスは柔軟性を持つ一方、横断的な問題への対応や機関間の調整不足という弱点があり、改革の方向性を論じる軸として使える",
