      "厚生労働省の2023年版労働経済白書によれば、非正規雇用労働者の割合は雇用者全体の約36%を占め、特に女性や若年層に集中しており、雇用の二極化が所得格差や社会保障格差に直結している。",
      "内閣府の2023年孤独・孤立対策に関する調査では、日本人の約4割が孤独感を「しばしば・常に感じる」または「時々感じる」と回答しており、2023年には孤独・孤立対策推進法が施行され制度的対応が始まった。",
      "文部科学省の2023年度調査では、不登校の小中学生数は約29万9千人と過去最多を更新しており、学校という制度への適応困難が社会的包摂の観点から問われている。",
