      "多様性と包摂の視点：ジェンダー・国籍・障害・経済階層などの属性による社会的排除がいかに再生産されるかを問い、インクルーシブな社会設計の必要性を論じる切り口。",
      "テクノロジーと社会変容の視点：SNSの普及や生成AIの登場が既存の社会関係・労働・教育にもたらす変化を、プラスとマイナス両面から分析し、技術決定論に陥らない社会学的考察を示す切り口。",
      "グローバルとローカルの緊張関係：少子高齢化・人口減少・移民政策・地方消滅といった日本固有の文脈と、国際的な持続可能な開発目標（SDGs）や人権規範との接点から課題を位置づける切り口。",
      "当事者参加とエージェンシーの視点：政策や支援が上から与えられるものではなく、当事者が社会変化の主体となるボトムアップ型の解決策を提案することで、社会学における行為者性の概念を実践的に示す切り口。",
