    suggestedStructure: "序論で自分が高校時代に取り組んだ探究テーマと問いを提示し、その課題が社会構造とどう結びついているかを社会学的概念で定義する。本論では収集したデータや事例をもとに原因・背景・影響を多角的に分析したうえで具体的かつ実現可能な解決策を提案し、結論でその解決策が社会全体にもたらす意義と今後の探究課題を示して締めくくる。",
