      "内閣府の孤独・孤立に関する実態調査（2021年）では、孤独感を「しばしば・常に感じる」と回答した割合が約4.5%に上り、若年層でも孤立が顕在化していることが示された",
      "国立社会保障・人口問題研究所の推計では、2050年には全世帯の約4割が単独世帯になると見込まれており、地域での見守り機能の需要が高まる一方で担い手が減少するという構造的矛盾が深刻化している",
      "民生委員の定員充足率は近年低下しており、地域の福祉的互助を担う人材確保が全国的な課題となっている",
      "デジタル庁が推進するデジタル田園都市国家構想では、ICTを活用したコミュニティ再編が政策として掲げられているが、高齢者のデジタルデバイドが地域内格差を生む懸念も指摘されている",
