      "防災・福祉・子育て支援など地域コミュニティが果たしてきた機能を行政・NPO・民間企業がどこまで代替できるか、あるいはできないかという公私の役割分担をめぐる論点",
      "都市部と農村部での地域コミュニティ変容の様相の違い、過疎化による消滅集落問題と都市部の匿名性・孤立問題を比較しながら論じる地域間格差の視点",
