      "創世記の創造物語（天地創造の6日間）は古代近東のバビロニア神話「エヌマ・エリシュ」と比較されることが多く、類似点と相違点の両方が学術的に論じられてきた",
      "旧約聖書における歴史観は「救済史（Heilsgeschichte）」と呼ばれ、歴史を神の摂理による直線的な進行として捉える点が古代ギリシャの循環的歴史観と対比される",
      "正義・隣人愛・社会倫理を訴える預言者文学（アモス・イザヤ書など）は、現代の社会正義論や解放の神学の思想的源泉として参照され続けている",
