      "日本では2023年時点で安楽死を合法化する法律は存在せず、終末期医療における意思決定ガイドラインが厚生労働省から示されているものの、宗教的価値観との接点は社会的議論の途上にある",
      "生命倫理の領域でしばしば参照されるトム・ビーチャムとジェームズ・チルドレスの「生命医学倫理の四原則」（自律尊重・善行・無危害・公正）は世俗的枠組みであり、キリスト教倫理との異同を比較することが論点整理に有効である",
