      "生命の始まりと終わりに関する決定権を神に帰属させるキリスト教的人間観と、個人の自律を最優先する近代的生命倫理との緊張関係を整理し、どのような対話が可能かを探る視点",
      "隣人愛・弱者への連帯というキリスト教的価値が、格差・貧困・難民問題など現代社会の構造的課題に対してどのような規範的指針を提供しうるかを論じる視点",
      "プロテスタントとカトリックの間でも倫理的立場が異なる事例を挙げ、キリスト教倫理を単一の声として語ることの限界と、多元的対話の必要性を指摘する視点",
      "世俗社会において宗教的倫理観が公共政策や法制度に影響を与えることの正当性と限界を問い、信仰に基づく価値観が「普遍的理性」の言葉で再提示されうるかどうかを考察する視点",
