      "生物的防除（天敵利用）は化学農薬の使用量削減に貢献するが、外来天敵の導入が在来生態系を攪乱した事例（例：オーストラリアにおけるオオヒキガエル導入）が知られており、導入前の厳密な評価が不可欠である",
