      "科学的不確実性と予防原則：因果関係が完全に証明されていない段階での規制判断において、予防原則を優先するか技術革新の促進を優先するかというガバナンス上の対立軸",
      "実験室知見から野外環境への外挿問題：制御された実験系で得られたデータが複雑な生態系においても同様に成立するかという、実験設計と生態学的妥当性に関する視点",
      "単一種最適化と系全体の最適化：特定の農業目標（収量最大化など）のために個々の生物間相互作用を操作することが、食物網全体の安定性にどう影響するかというシステム思考の視点",
