    suggestedStructure: "序論で科学技術の二面性という概念を農業・生命科学の文脈で定義し具体的な生物間相互作用の例を提示したうえで、本論では実験設計の妥当性と変数制御の論理・応用可能性と生態系リスクのトレードオフを順に展開し、結論では不確実性を認めながらも科学的知見を社会実装につなげる際の判断基準や倫理的配慮を自分の言葉でまとめるとよい。",
