      "国内事例としてフローレンスは病児保育という社会課題に対してサブスクリプション型の収益モデルを組み合わせ、事業継続性と社会的インパクトの両立を実現した先行事例として認知されている",
      "SDGs（持続可能な開発目標）が2030年を達成期限として掲げる17目標は、ソーシャルビジネスが取り組むべき課題領域を具体化しており、企業のビジネス戦略との接続点として機能している",
      "ESG投資の世界規模は2022年時点で30兆ドルを超えるとされており、社会課題解決と収益性を兼ねるビジネスモデルへの資本流入が加速している傾向がある",
