      "シンガポールは英語・中国語・マレー語・タミル語の4言語を公用語とする多言語政策を採用し、経済競争力と民族的多様性の両立を図るモデルとして注目されている",
      "ユネスコは2003年に無形文化遺産保護条約を採択しており、言語を文化的アイデンティティの核として保全する国際的枠組みが整備されつつある",
