      "社会復帰と更生促進の観点から、GPS監視によるスティグマ効果が社会復帰を阻害し逆に再犯リスクを高める可能性があるという視点と、監視による継続的な支援・介入が更生を促すという視点の対立",
      "立法政策上の代替手段論として、GPS装着以外の再犯防止策（認知行動療法の義務化、保護観察の強化、居住地制限など）との比較において、GPS装着がより制限的な手段かどうかを検討する視点",
