    suggestedStructure: "序論でSNS普及による情報環境の変化（フィルターバブルや誤情報拡散など）を具体的に示して問題提起し、本論で現行の情報リテラシー教育の取り組みと限界を整理しつつ教育主体の役割分担や必要なリテラシーの中身について自分の立場から論じ、結論で社会全体として個人・学校・企業・政府が連携する方向性を示して締める。",
