      "日本政府のGX(グリーントランスフォーメーション)推進法が2023年に成立し、今後10年間で官民合わせて150兆円超の投資を見込むとしており、工学的技術開発への資金動員規模が示されている",
      "再生可能エネルギーのコストは世界的に低下しており、太陽光発電のコストは2010年比で2022年時点において約9割以上下落したとIEAは報告しているが、日本国内の系統安定化・蓄電技術の整備は依然課題として残っている",
      "CCUS(二酸化炭素回収・利用・貯留)技術は現状で商用規模での普及が限られており、回収コストの大幅低減と貯留適地の確保が実用化に向けた主な工学的ハードルとなっている",
