    suggestedStructure: "序論でカーボンニュートラルの定義と工学が果たすべき役割を簡潔に示したうえで、本論では再生可能エネルギーの拡大・水素などの新エネルギーキャリア・CCUSや省エネ技術といった複数の工学的アプローチをそれぞれの可能性と課題とともに論じ、結論で技術間の相互補完性や社会実装に向けた工学者の責務を述べてまとめる。",
