      "米国・ロシア・中国など主要軍事大国はLAWS開発への投資を継続しており、特定の規制に消極的な姿勢を示す一方、オーストリア・ブラジルなど30か国以上が事前の禁止条約締結を求めている",
      "国際赤十字委員会（ICRC）は2021年に公表した立場文書の中で、純粋に自律的な兵器システムに対する法的・倫理的懸念を表明し、人間による意味ある制御の必要性を強調した",
