    suggestedStructure: "序論でLAWSの定義と既存国際法による規制の空白という問題状況を提示し、本論で法的観点（区別原則・責任帰属の問題）と倫理的観点（人間の尊厳・自律的殺傷の許容性）を順に論じ、結論で人間による意味ある制御を確保するための国際的規制枠組みの方向性について自身の見解を示す構成が有効である。",
