      "里地里山は農業・林業・採草などの人間活動によって維持されてきた二次的自然環境であり、日本の絶滅危惧種の約44%がこの環境に生息するとされ、農業の放棄による荒廃が保全上の課題となっている",
      "有機農業は慣行農業と比較して農地内の生物種数を平均30%程度増加させるという欧州の複数のメタ分析結果が存在し、農薬・化学肥料の削減が生物多様性に有効とされている",
