      "ユニクロを展開するファーストリテイリングは2023年にサプライチェーン上の人権デュー・ディリジェンス体制を公表し、取引先工場の労働環境監査を強化したが、国際NGOから継続的な批判を受けるなど課題も残る",
      "日本では2022年に改訂されたコーポレートガバナンス・コードにより、プライム市場企業はサステナビリティ方針の開示と取締役会での監督体制の整備が求められるようになった",
