      "グローバルサプライチェーンにおける人権・労働問題への責任範囲をどこまで企業に求めるべきかという境界の問題は、先進国企業と途上国の生産現場との非対称な関係を含む多層的な論点を提供する",
      "CSRの推進が企業の競争力強化や長期的な企業価値向上につながるというビジネスケースの側面と、それが社会的公正の実現を企業任せにしてしまうリスクという政府・市場の役割分担の問題を対比することができる",
