    suggestedStructure: "序論では講義で提示された中心的な問いや発見を端的に示し自分が着目した論点を明示する。本論では講義内容を正確に踏まえながら複数の視点から分析・考察し根拠を示して自分の見解を展開し、結論でその考察が生命科学の研究や社会にとって持つ意味を簡潔にまとめ今後の問いへとつなげる。",
