      "世界経済フォーラムが発表するジェンダーギャップ指数において日本は2023年に146カ国中125位であり、形式的な男女平等の法整備と実質的な公平の達成のあいだに大きな乖離が存在することを示している",
      "教育分野では、所得水準と学力・進学率の相関が国内調査で繰り返し確認されており、同一カリキュラムを与える形式的平等だけでは出発点の格差が拡大するという批判が根強い",
      "アファーマティブ・アクション（積極的格差是正措置）は米国の大学入試において2023年に最高裁が違憲判決を下したことで世界的に議論を呼び、公平実現のための手段とその限界をめぐる論点を提供している",
