      "日本の介護離職者数は年間約10万人前後で推移しており、家族の介護という形の不自由が就労や個人の生活設計を制約している現実がある",
      "ジャン＝ポール・サルトルは「人間は自由の刑に処されている」と述べ、自由とは必ずしも快適なものではなく責任と表裏一体であるという視点を示した",
      "文芸の世界では松尾芭蕉に代表される俳句が五七五という厳格な制約の中で豊かな表現を生み出してきた歴史があり、制約と創造の関係を考える素材となる",
