      "総合型選抜では出願書類（志望理由書・活動報告書）と小論文・面接を組み合わせて評価することが多く、小論文では専門的関心の深さと論理的思考力が重視される",
      "各学科の専門分野は社会課題と密接に結びついており、例えば社会福祉学では少子高齢化・ケア人材不足、情報科学ではAIやデジタル化の倫理問題などが近年の重要テーマとなっている",
      "探究学習の充実を掲げた学習指導要領（2022年度高校全面実施）により、高校生が自らテーマを設定して調査・論述する力が以前より重視されるようになっている",
