    suggestedStructure: "序論で身近な人々の具体的な健康上の問題点を観察・特定し問題意識を示したうえで、本論では問題の背景要因を経済学・行動科学の視点から分析しつつ実現可能な取り組みを複数提案してその根拠と課題も論じ、結論で取り組みの波及効果や社会的意義に言及して自分なりの提言としてまとめる構成が有効である。",
