      "文部科学省は2023年7月に学校における生成AIの利用に関するガイドラインを公表し、教育現場での適切な活用と不正利用防止の両立を求めた",
      "欧州連合（EU）のAI規制法は2024年に成立し、高リスクAIシステムには事前適合性評価を義務付けるなど、国際的な規制の先行事例となっている",
      "国際労働機関（ILO）の2023年報告書では、生成AIは完全な雇用代替よりも職務内容の補完・変容をもたらす可能性が高いと分析されている",
