      "符号化・復号化モデルの限界という軸。送受信モデルはコミュニケーションを線形的・機械的に捉えるが、実際の人間のコミュニケーションは共同で意味を構築するダイナミックなプロセスであるという批判的視点から、コードとしての言語観の射程と限界を論じられる",
