      "2023年のSAG-AFTRAおよびWGA（全米脚本家組合）のストライキでは、AIによる脚本生成や俳優の顔・声のデジタル複製に関するルール整備が主要な交渉議題となり、約150日間に及ぶ歴史的な労働争議となった",
      "映像制作におけるVFXやCGの自動化・AI支援はすでに実用段階にあり、ポストプロダクションのコスト削減や制作期間の短縮に寄与している一方、中小規模のVFXスタジオの人員削減が報告されている",
      "AIが生成したコンテンツの著作権について、日本の著作権法では現時点で人間の創作行為を前提としており、AI単独生成物の著作権帰属は法的に未確定な状態が続いている",
      "ディープフェイク技術の悪用による偽情報動画の拡散が社会問題化しており、EUのAI Act（2023年暫定合意）ではAI生成コンテンツへのラベリング義務化が検討されている",
