      "近年の入試改革議論では、記述式評価における採点の公平性と再現性の担保が課題として繰り返し指摘されており、小論文・AO型入試の設計に直接影響している",
      "日本語の要約能力に関する研究では、要約の質は単語知識よりも文章構造の把握力（マクロ構造理解）と相関が高いことが複数の教育言語学研究で示されている",
