      "WHOの推計によれば、身体不活動は世界の非感染性疾患による死亡の重要リスク因子であり、十分な身体活動によって2型糖尿病・心疾患・一部のがんリスクを20〜30%程度低減できるとされている",
      "高強度インターバルトレーニング（HIIT）は短時間で最大酸素摂取量や心肺機能を向上させる効果が複数のランダム化比較試験で確認されており、時間的制約のある成人への運動処方として注目されている",
      "日本の国民医療費は2022年度に約46兆円を超え、生活習慣病関連が大きな割合を占めることが報告されており、予防的介入としての運動推進の経済的意義が高まっている",
