      "エビデンスの種類と実践への乖離という視点。ランダム化比較試験で効果が示された運動プログラムが実際の公衆衛生施策に普及しにくい要因として、継続率・アクセス格差・コストなどを挙げながら、科学知識の社会実装の課題を論じることができる",
