      "2022年に政府が策定した「デジタル田園都市国家構想」では、デジタル技術を活用した地方移住・産業振興を目指し、地方自治体へのデジタル基盤整備支援が盛り込まれた",
      "観光庁のデータによると、インバウンド需要の回復とともに地方観光地での消費拡大が期待されているが、地域内への経済波及効果には地域ごとに大きなばらつきがある",
      "農林水産省の6次産業化推進政策では、農業生産・加工・販売を一体化することで農村地域の付加価値向上と雇用維持を図る取り組みが各地で展開されている",
