    backgroundKnowledge: "グローバル社会とは、人・モノ・情報・資本が国境を越えて流動する現代の国際秩序を指す。冷戦終結後の1990年代以降、WTO設立やインターネットの普及によって経済的・文化的相互依存が深まった一方、格差の拡大・環境問題・移民難民問題・情報操作など複合的な課題も顕在化している。龍谷大学国際学部は仏教的人間観を基盤に多文化共生や平和構築を学問的軸に置いており、単なる経済合理性だけでなく人道・公正の視点から課題を捉える姿勢が評価されやすい。",
