    suggestedStructure: "序論でグローバル社会の特徴と自分が焦点を当てる課題（例：格差・環境・移民など一つ）を明示し、本論で背景・現状・問題の構造を分析したうえで具体的な解決策または課題の方向性を論じ、結論で国際的連帯と個人・社会の役割に触れながら自分の見解をまとめる。",
