    suggestedStructure: "冒頭で自分が注目するメディアの具体的な問題や現象を提示し、その背景にある構造的要因を中盤で分析したうえで、受け手としての個人または社会全体がどのように向き合うべきかという提言で締めくくる流れが、論理の展開として説得力を持ちやすい。プレゼンテーションでは問題提起・現状分析・自分の見解の三段構成を意識すると質疑応答でも軸がぶれにくい。",
