      "デジタル庁の推進するDX（デジタルトランスフォーメーション）政策の進展により、経済・ビジネス分野でもデータ分析やAI活用の素養を持つ人材需要が高まっており、2030年には約79万人のIT・データ人材不足が予測されている（経済産業省試算）",
      "文部科学省の学習指導要領改訂（2022年度以降）および大学教育においても、主体的・対話的で深い学び（アクティブラーニング）が推奨されており、自律的な学習計画立案能力が学生に求められている",
      "世界経済フォーラム（2023年）の未来の仕事レポートでは、2027年までに需要が高まるスキルとして分析的思考・創造的思考・技術リテラシー・社会的影響への配慮が上位に挙げられている",
