    suggestedStructure: "序論で自分が成し遂げたい目標と職業ビジョンを簡潔に提示し、本論前半で目標実現に必要な職業人としての資質・スキルを経済学的観点から根拠とともに説明、本論後半で成蹊大学経済学部の具体的なカリキュラムや活動と対応させた4年間の学業計画を段階的に論じ、結論で社会への貢献という視点から自分の目標の意義を改めて締めくくる構成が効果的である。",
