      "2023年の非正規雇用比率は全雇用者の約37%前後で推移しており、賃金格差と社会保険カバレッジの問題が継続している",
      "GX（グリーントランスフォーメーション）推進のため政府は2023年にGX推進法を成立させ、今後10年で150兆円規模の官民投資を目標として掲げている",
