      "AIや生成AIの普及に伴い、著作権法・個人情報保護法・不法行為責任など既存の法制度との整合性についての議論が国内外で進んでおり、日本でも2023年以降に関係省庁が検討を重ねている",
      "2023年のLGBTQ理解増進法成立を受け、同性婚や性的少数者の法的地位に関する憲法24条の解釈論や立法政策論が実務・学術の両面で活発に論じられている",
      "少年法は2022年改正により18歳・19歳を「特定少年」として一部厳罰化したが、教育的処遇と応報的処罰のバランスに関する刑事法・少年法政策上の議論が継続している",
