      "国内消費市場では少子高齢化の影響で国内需要の縮小が続いており、企業は新興国市場への進出や新たな価値創造によるイノベーションで成長を模索している",
      "SDGsへの対応として、ESG投資市場が世界的に拡大しており、企業の環境・社会・ガバナンスへの取り組みが企業価値や消費者の購買行動に影響を与えるようになっている",
      "SNSを活用したマーケティングはZ世代を中心とした若年消費者へのリーチに効果的であり、インフルエンサーマーケティングやコンテンツマーケティングへの企業支出が年々増加している",
