      "Adobe社は2013年にパッケージ販売からサブスクリプション型（Creative Cloud）へ完全移行し、売上の安定化と顧客データ活用による製品改善を実現した事例として広く知られる",
      "特定商取引法の2022年改正により、日本では定期購入契約の申込画面での明確な表示義務が課され、消費者保護の観点からサブスクビジネスへの規制が強まっている",
      "サブスクリプションモデルでは顧客生涯価値（LTV）と解約率（チャーンレート）が経営上の重要指標となり、従来の販売数量を重視した経営指標とは異なるマネジメント手法が求められる",
