      "言語を守ることは過去の文化への固執か、それとも未来への積極的継承かという価値観の違い。伝統保護と社会適応のどちらを優先するかという世代間・地域間の対立を論点として取り上げられる",
      "日本語という母語を前提に自身のアイデンティティを問い直す視点。日本語話者が英語や他言語を習得する過程で自己認識がどう変容するかを素材にすることで、論述に具体性と一人称的説得力を加えられる",
