    suggestedStructure: "序論では言語とアイデンティティの関係を定義し自分の主張を明示する。本論前半で言語が思考・価値観・集団帰属感を形成するメカニズムを具体例（継承語研究や消滅危機言語の事例など）を用いて論じ、後半でグローバル化という反論的文脈を踏まえたうえで言語保護や多言語共存の意義を考察し、結論で異文化コミュニケーションの観点から言語的多様性を尊重することの現代的意義を述べてまとめる。",
