    backgroundKnowledge: "「覚える」とは情報を記憶に保持する行為であり、「分かる」とは情報の意味や構造を理解し他の知識と関連づけられる状態を指す。教育心理学ではブルームのタキソノミー（学習目標の分類学）において「記憶」と「理解」は異なる認知プロセスとして区別されており、記憶は最も基礎的な認知レベル、理解はそれより高次の認知レベルに位置づけられる。看護教育においては疾患の知識を暗記するだけでなく、患者の状態に応じて判断・応用できる「理解」が臨床実践の質に直結するとされる。日本の教育政策においても2020年代の学習指導要領改訂では「主体的・対話的で深い学び」が重視されており、単なる知識の習得を超えた意味理解や思考力の育成が求められている。",
