    suggestedStructure: "序論で平和追求に内在する代表的な矛盾（例：武力による平和維持か、主権対人権か）を問いとして提示し、本論でその矛盾が生まれる国際法上・国際関係上の構造的要因を具体的事例とともに二つ程度掘り下げたうえで、結論ではその矛盾を完全に解消することは困難だが国際社会がいかなる方向性でバランスを模索すべきかを自らの見解として示す。",
