      "最高裁判所は2023年の朝日訴訟の流れを受けた一連の保護基準引き下げ訴訟において、厚生労働大臣の裁量権の範囲と最低生活費算定の合理性が争点となっており、各地の高裁段階で判断が分かれている",
      "生活保護法4条2項が定める扶養義務者への扶養照会は法的義務ではなく運用上の慣行であるが、申請をためらわせる心理的障壁として機能しているという指摘が法学者・支援団体から相次いでいる",
      "生活保護費の不正受給件数は全受給件数の約0.5%前後とされており、制度の不正利用が問題の本質ではなく申請抑制こそが課題であるという論点が提起されている",
