    suggestedStructure: "序論では超高齢社会の現状と地域包括ケアシステムの理念を簡潔に示し、本論では人材不足・財源問題・地域間格差・多職種連携の困難といった具体的課題を複数の視点から分析したうえで、デジタル活用や住民参加型の互助機能の強化など解決の方向性を論じる。結論では課題解決に向けた自分の見解を述べ、システムが担う「尊厳ある老い」という本質的価値に立ち返ることで論述を締めくくる。",
