    suggestedStructure: "序論で自身が取り組んだ科学分野の発見・知見を一つ具体的に提示しつつ科学的発見が社会に影響を与えるという問いを立て、本論では正のインパクトと潜在的リスクの両面をその発見を軸に論証したうえで研究者に求められる社会的責任に言及し、結論で自身が将来どのような姿勢で科学に向き合うかという主体的な展望を示して締めくくる。",
