    suggestedStructure: "序論で技術と社会の共進化という概念を簡潔に定義し問いの方向性を示したうえで、本論では具体的な技術事例を一つか二つ取り上げ技術が社会を変えた側面と社会が技術を規定した側面の双方を論証し、結論ではシステムデザインの担い手として共進化を設計的に捉える視点の重要性を述べて締めくくる構成が効果的である。",
