    suggestedStructure: "序論で具体的な都市問題（例：空き家増加と人口縮退、または気候変動対応）を提示し持続可能性と市民参加の両概念を定義したうえで、本論では当該問題における市民参加の現状と課題を論じつつ参加の質的向上や制度改善の具体的方向性を自分の視点で論証し、結論でその展望と都市政策科学的観点からの示唆をまとめる構成が適切である。",
