    backgroundKnowledge: "経済格差の拡大はグローバル化・技術革新・資本収益率の上昇（ピケティのr>g命題）などを背景に先進国・途上国双方で深刻化しており、政府は再分配政策や累進課税、社会保障の強化で対応を試みている。一方、気候変動問題はパリ協定（2015年）のもと各国がNDC（国別貢献目標）を設定し対応を進めているが、歴史的排出責任の大きい先進国と経済成長を優先したい途上国との間で公平性をめぐる緊張が続いている。両テーマは「誰が費用を負担すべきか」という分配的正義の問いで交差しており、経済学・倫理学・国際関係論にまたがる複合的論点を形成する。",
