      "経済成長と気候変動対策をトレードオフとして捉える従来の見方に対し、グリーン投資や脱炭素技術が雇用創出と成長を両立させうるという「グリーン成長」論を検討し、その実現条件や限界を吟味する軸",
      "国内格差と国際格差を連続した問題として捉え、国内再分配政策（累進課税・社会保障）と国際的な気候資金移転（緑の気候基金など）の類比から、グローバルな連帯と主権の間の緊張を論じる視点",
      "短期的な経済コストと長期的な気候リスク・格差固定化リスクの時間的割引率をめぐる問題を設定し、現世代と将来世代の間の世代間公正という倫理的次元を加える軸",
