    suggestedStructure: "序論で経済格差と気候変動という二つの問題が「誰がコストを誰に転嫁するか」という共通の分配問題として結びついていることを示したうえで、本論前半で格差拡大の構造的要因と政府対策の有効性・限界を検討し、本論後半で国家間の公平性論争と経済成長との両立可能性を論じ、結論では両問題を横断する政策原則（例：炭素税収入の逆進性補正への活用や国際的な気候資金の拡充）を提示してまとめる。",
