      "東京大学の入学者のうち父母の年収が950万円以上の世帯が半数近くを占めるという調査結果が複数の研究で指摘されており、高等教育における経済的格差の集積を示している",
      "ピエール・ブルデューの「文化資本」概念は、学力や教養が家庭環境を通じて世代間で継承されることを理論化しており、格差の再生産を説明する枠組みとして広く参照される",
      "歴史教育の目的について、ユネスコは「過去の失敗から学び平和的共存を実現する市民を育てること」を掲げており、個人の教養形成と社会的責任の涵養という二重の役割が強調されている",
      "日本の大学進学率は2022年時点で約56%前後であるが、世帯収入による進学率の格差は依然として顕著であり、奨学金制度の整備が政策課題として議論されている",
