    suggestedStructure: "序論で宇野の論旨を正確に要約しつつ民主主義の危機という問いを自分の言葉で再定義し、本論では宇野が示す危機の構造的要因（代表制の空洞化・熟議の消滅・少数者排除）のうち最も重要と考える論点を一つ選んで現代の具体的事例と照応させながら深掘りし、結論ではその危機に対して個人・社会・制度のどのレベルでどのような応答が可能かを展望して締めくくる。",
