      "OECDのPISA2022調査において日本の15歳生徒の数学的リテラシーは世界5位、読解力は3位と高水準を維持しているが、学習意欲や学校への帰属意識はOECD平均を下回る項目がある。",
      "文部科学省の2022年度学校基本調査では、教員の時間外在校等時間が依然として長く、小学校教諭の約3割、中学校教諭の約5割が月45時間超の時間外業務を行っているとされる。",
      "日本の教育費の公的支出のGDP比はOECD加盟国の中で下位に位置しており、家庭の経済格差が学力格差に影響する構造的問題が継続して指摘されている。",
      "デジタル教育の推進として2019年度からGIGAスクール構想が始まり、2021年度末には公立小中学校の児童生徒1人1台端末の整備がほぼ完了したが、活用格差や教員のICTスキル差が新たな課題として浮上している。",
