    suggestedStructure: "まず設問が指示するグラフや資料の該当箇所を正確に特定して事実を端的に述べ、次にその数値変化や傾向が生じた社会的・教育的背景を自分の知識と結びつけて説明し、最後に問いが求める含意や課題・展望を簡潔にまとめる流れが、100〜400字の各設問に対応する基本構成となる。",
