      "文化庁の調査では、日本語教育を必要とする外国人のうち日本語学習機会を十分に得られていない層が依然として多く、情報アクセスや行政手続きにおける言語障壁が社会参加の主要な障害として指摘されている",
      "国際移住機関（IOM）によれば、世界の国際移民数は2020年時点で約2億8千万人を超えており、受入国における統合政策の質が社会的結束に大きく影響するとされている",
