    suggestedStructure: "序論では日本社会における在留外国人増加の現状と多文化共生の定義を示しながら主要課題を一つ絞って問題提起し、本論では言語バリアや教育機会の不平等など具体的課題を根拠とともに分析しつつ自分が国際学部での学びを通じて何をどう実践できるかを論じ、結論では個人の貢献と社会変革のつながりを展望として締めくくる流れが有効である。",
