    suggestedStructure: "序論で持続可能な観光が求められる背景としてオーバーツーリズムや地域衰退の現状を示し、本論では環境保全・地域経済・住民参加の三側面から課題を整理したうえで量から質への転換や地域主導のガバナンス強化という方策を具体例とともに論じ、結論で観光が地域活性化と持続可能な社会の双方に資するための今後の展望を自分の考えとして締めくくる。",
