      "外国人労働者数は2023年時点で過去最多水準を更新しており、技能実習制度の人権侵害リスクについて国連特別報告者からも改善勧告が出されている",
      "日本では同性婚が法律上認められておらず、複数の地裁判決で婚姻の平等に関する違憲・違憲状態判断が相次いでいるが、立法による解決は2024年時点で未実現である",
