      "屋久島や西表島など日本のユネスコ世界自然遺産地域では、オーバーツーリズムによる植生踏み荒らしや野生動物への影響が報告されており、入域料や利用者数制限の議論が進んでいる",
      "観光庁の調査ではコロナ禍以降、旅行者の間で「自然・農山漁村体験」や「環境配慮型旅行」への関心が高まりつつあることが示されており、エコツーリズム需要の潮流変化が見られる",
      "オーバーツーリズムが深刻化した地域（京都・鎌倉・富士山周辺など）では、大量観光が地域住民の生活環境や文化財に悪影響を及ぼすとして、持続可能な観光モデルへの転換が課題とされている",
