      "グローバルな観光需要とローカルな生態系の脆弱性という緊張関係：訪問者の増加が持つ正の側面（保全財源の確保、啓発効果）と負の側面（踏圧・騒音・廃棄物・野生動物への影響）をどう評価するか",
      "制度設計の有効性という視点：入域料・利用者数上限・ガイド同行義務などの規制手段が実際に機能するか、また誰が管理・監視コストを負担するのかという政策的実現可能性の問い",
      "持続可能性の定義をめぐる視点：SDGsにおける持続可能な観光とは環境面だけでなく社会的・経済的公正も含む概念であり、エコツーリズムが真の意味で「誰のための持続可能性か」を問う社会学的切り口",
