      "運に対する選手の心理的対処（メンタルマネジメント）がパフォーマンスに与える影響という視点から、準備・集中・切り替えの重要性を論じる方向性",
      "テクノロジーの進化によって運の排除は可能か、またそれはスポーツの本質を豊かにするのか損なうのかというスポーツ倫理・哲学的な問いを軸にする視点",
